from dotenv import load_dotenv
from langchain_openai import ChatOpenAI
from langchain_ollama import ChatOllama
from langchain.tools import tool
from langchain_core.messages import HumanMessage
from langchain.agents import create_agent
from tavily import TavilyClient

load_dotenv()

tavily = TavilyClient()

@tool
def search_tool(query: str):
    """
    A simple search tool that takes a query string and returns a search result.

    arguments:
    - query: The search query string.

    returns:
    - A string representing the search result.
    """

    print(f"Searching for: {query}")
    return tavily.search(query = query)

llm = ChatOllama(model="qwen2.5:3b")

tools = [search_tool]
agent = create_agent(model=llm, tools=tools)

def main() -> None:
    query = "Search the job openings for Software Engineer/AI Engineer in India for 3+ years of experience and list their details."
    result = agent.invoke({
        "messages": [HumanMessage(content=query)],
    })

    print(result)

if __name__ == "__main__":
    main()

